type SyncOutcome =
  | { status: 'applied'; newVersion: number }
  | { status: 'conflict'; server: WorkOrder; base: number }

async function syncWorkOrder(local: WorkOrder): Promise<SyncOutcome> {
  // local.baseVersion = the server version this edit was made against
  const res = await api.put(`/work-orders/${local.id}`, local, {
    headers: { 'If-Match': String(local.baseVersion) },
  })

  if (res.status === 412) {
    // Server moved on since baseVersion — DO NOT overwrite.
    const server = await api.get<WorkOrder>(`/work-orders/${local.id}`)
    return { status: 'conflict', server, base: local.baseVersion }
  }

  const newVersion = res.data.version
  await db.markSynced(local.id, newVersion) // clears dirty flag
  return { status: 'applied', newVersion }
}

