type WorkOrder = { id: string; baseVersion: number; status: string; notes: string; updatedAt: number }

export function resolveConflict(local: WorkOrder, server: WorkOrder) {
  // 1. DETECT: base version the client started from vs the server's current version.
  if (local.baseVersion === server.baseVersion) {
    return { outcome: 'no-conflict', winner: local }
  }

  // 2. APPLY: status is safety-critical -> never auto-merge, queue for a human.
  if (local.status !== server.status) {
    return { outcome: 'manual', winner: null, conflict: { local, server } }
  }

  // 3. Notes are additive -> field-merge instead of overwrite.
  const merged: WorkOrder = {
    ...server,
    notes: server.notes + '\n--- offline addendum ---\n' + local.notes,
    baseVersion: server.baseVersion + 1,
  }

  // 4. TRACE: the loser is never discarded silently.
  emit('sync_conflict_resolved', { id: local.id, strategy: 'field-merge', loser: server.notes })
  return { outcome: 'merged', winner: merged }
}

