import * as Keychain from 'react-native-keychain'

const REFRESH_KEY = 'auth.refresh'

// Access token: short-lived, kept in memory only (lost on kill — by design).
let accessToken: string | null = null

export async function persistRefreshToken(token: string): Promise<void> {
  await Keychain.setGenericPassword('refresh', token, {
    service: REFRESH_KEY,
    // Hardware-backed: Keystore (Android) / Secure Enclave-guarded Keychain (iOS).
    accessControl: Keychain.ACCESS_CONTROL.BIOMETRY_ANY_OR_DEVICE_PASSCODE,
    // Available after first unlock so a background sync can refresh — but NOT before.
    accessible: Keychain.ACCESSIBLE.AFTER_FIRST_UNLOCK_THIS_DEVICE_ONLY,
  })
}

export async function loadRefreshToken(): Promise<string | null> {
  const creds = await Keychain.getGenericPassword({ service: REFRESH_KEY })
  return creds ? creds.password : null
}

export function setAccessToken(t: string | null): void {
  accessToken = t // never persisted to disk
}

export async function clearTokens(): Promise<void> {
  accessToken = null
  await Keychain.resetGenericPassword({ service: REFRESH_KEY })
}

