async function attachRepairPhoto(job: Job): Promise<AttachResult> {
  // Request at point-of-use, with a rationale the OS dialog can't give
  const status = await Permissions.check('camera')
  if (status === 'blocked') {
    // OS-level 'Don't ask again' / iOS revoked — cannot re-prompt
    analytics.track('permission_blocked', { cap: 'camera', jobId: job.id })
    return degrade(job, 'Photo unavailable — add a note, attach later from Settings')
  }
  if (status !== 'granted') {
    await showRationale('Photos verify the repair for the customer record.')
    const asked = await Permissions.request('camera')
    if (asked !== 'granted') {
      analytics.track('permission_denied', { cap: 'camera', jobId: job.id })
      return degrade(job, 'Continuing without a photo — you can add one later')
    }
  }
  const photo = await Camera.capture()             // only reached when granted
  await SecureStore.putEncrypted(`job:${job.id}:photo`, photo)  // Keystore / Keychain
  return { ok: true, attached: true }
}

function degrade(job: Job, message: string): AttachResult {
  Toast.show(message)
  return { ok: true, attached: false }   // ok:true — the JOB is not blocked
}

