async function syncPendingWork(draft: Draft, session: Session): Promise<SyncResult> {
  // 1. Auth clock, not data clock: is the token still valid?
  if (session.isExpired()) {
    await queue.enqueue(draft)          // hold the write — do NOT drop it
    const refreshed = await tryRefresh(session)
    if (!refreshed) {
      return { status: 'queued-offline', keptLocal: true }
    }
    session = refreshed
  }

  // 2. Only now, with a valid token, may we touch the server.
  const remote = await server.fetch(draft.id)
  if (remote.updatedAt > draft.baseVersion) {
    return { status: 'conflict', local: draft, remote } // surface, never auto-overwrite
  }

  // 3. Reconcile — server accepts the queued write.
  await server.push(draft)
  await queue.clear(draft.id)
  return { status: 'synced', keptLocal: false }
}

