// Allowlist — the ONLY fields permitted to leave the device.
const SAFE_FIELDS = ['job_id', 'region', 'app_version', 'schema_ver'] as const
type SafeEvent = { name: string; props: Record<string, string | number> }

export function emit(name: string, raw: Record<string, unknown>): void {
  const props: Record<string, string | number> = {}
  for (const key of SAFE_FIELDS) {
    const v = raw[key]
    if (typeof v === 'string' || typeof v === 'number') props[key] = v
  }
  // Coarsen location to region; never ship lat/lng breadcrumbs.
  props.coarse_ts = Math.floor(Date.now() / 3_600_000) // hour bucket
  const safe: SafeEvent = { name, props }
  offlineQueue.enqueue(safe) // secure storage — only redacted payloads persist
}

// Field-note text, customer name, address, GPS, EXIF NEVER reach the queue:
emit('job_saved', { job_id: 'J-8821', region: 'IL-NE', note: rawNote, gps: fix })

