type ViewState =
  | { kind: 'loading'; cached: WorkOrder[] }        // never blank: show cache under skeleton
  | { kind: 'empty' }                               // 200, zero rows -> 'No jobs assigned'
  | { kind: 'error'; cached: WorkOrder[]; reason: 'offline' | 'server' }
  | { kind: 'loaded'; orders: WorkOrder[]; pendingEdits: number }

function reduce(prev: ViewState, ev: FetchEvent): ViewState {
  switch (ev.type) {
    case 'START':
      return { kind: 'loading', cached: cacheRead() }
    case 'OK':
      return ev.rows.length === 0
        ? { kind: 'empty' }
        : { kind: 'loaded', orders: merge(ev.rows, cacheEdits()), pendingEdits: cacheEdits().length }
    case 'FAIL':
      return { kind: 'error', cached: cacheRead(), reason: isOffline() ? 'offline' : 'server' }
  }
}

