import { Pressable, Text, AccessibilityInfo } from 'react-native'

export function WorkOrderCompleteButton({ order, saveOffline }: Props) {
  async function onComplete() {
    await saveOffline(order.id)               // local write = source of truth
    AccessibilityInfo.announceForAccessibility(
      'Job completed. Saved offline. Will sync when back online.'
    )
  }

  return (
    <Pressable
      onPress={onComplete}
      accessible
      accessibilityRole="button"
      accessibilityLabel={`Complete job ${order.number}`}
      accessibilityState={{ disabled: order.synced }}
      accessibilityHint="Saves the job now, even offline"
    >
      <Text>Complete job</Text>
    </Pressable>
  )
}

