async function onSwipeComplete(order: WorkOrder): Promise<void> {
  // 1. Durable intent FIRST — before any network, before backgrounding can kill us
  const intent: SyncIntent = {
    id: crypto.randomUUID(),
    orderId: order.id,
    action: 'complete',
    baseRev: order.rev,          // what we believed when the tech swiped
    at: Date.now(),
  }
  await secureStore.put(`intent:${intent.id}`, intent)  // encrypted at rest
  await syncQueue.enqueue(intent)                        // survives app kill

  // 2. Optimistic UI — the tech sees 'done' with an offline badge
  ui.markComplete(order.id, { pending: true })

  // 3. Flush is lifecycle-safe: runs on reconnect AND on app foreground
  await syncQueue.flush().catch(() => {/* stays queued, no data loss */})
}

async function reconcile(intent: SyncIntent): Promise<void> {
  const server = await api.getOrder(intent.orderId)
  if (server.rev !== intent.baseRev) {
    // Conflict: someone/something moved the order since the swipe
    await conflictLog.record(intent, server)   // surfaced, never silent
    return resolveConflict(intent, server)      // policy decides, not a blind overwrite
  }
  await api.completeOrder(intent.orderId, intent.baseRev)
  ui.markComplete(intent.orderId, { pending: false })
}

