// Fires on the ONE path crash reporting can't see: a resolved offline-sync conflict.
export function onSyncConflict(local: EditRecord, remote: EditRecord, policy: ConflictPolicy) {
  const overwrote = policy === 'last-write-wins' && remote.updatedAt > local.updatedAt

  analytics.track('sync_conflict_resolved', {
    record_id: local.recordId,
    policy,                              // last-write-wins | merge | manual
    resolution: overwrote ? 'remote_overwrote_local' : 'local_kept',
    local_age_ms: Date.now() - local.updatedAt,
    remote_age_ms: Date.now() - remote.updatedAt,
    was_backgrounded: appLifecycle.wasBackgroundedDuringEdit,
    network_transition: netMonitor.lastTransition, // offline->online
    fields_lost: overwrote ? diffFields(local, remote) : [],
  })

  if (overwrote && local.hasUnsyncedUserInput) {
    // Escalate a silent data-loss risk to crash reporting as a non-fatal.
    crashReporter.recordNonFatal(new SilentOverwriteWarning(local.recordId))
  }
}

